import pyomo.environ as pyo

# ---------------------------------------------------------------------------
# All numeric constants from the problem statement live here.
# ---------------------------------------------------------------------------
DATA = {
    "L": 24.0,            # cardboard length (inches)
    "W": 36.0,            # cardboard width  (inches)
    "grid_steps": 24,     # number of candidate side lengths on a uniform grid
    "big_m": 100.0,       # big-M for linking constraints
}

# Candidate side lengths (inch): uniform grid over [0, max_side]
_MAX_SIDE = min(DATA["L"], DATA["W"]) / 2.0
_CANDIDATES = [
    round(_MAX_SIDE * k / DATA["grid_steps"], 6)
    for k in range(0, DATA["grid_steps"])   # exclude the degenerate max_side itself
]

DATA["candidates"] = _CANDIDATES
DATA["max_side"] = _MAX_SIDE


def build_model(data=None):
    d = data or DATA

    L = d["L"]
    W = d["W"]
    M = d["big_m"]
    cands = d["candidates"]

    model = pyo.ConcreteModel()

    # ---- Set of candidate side lengths -------------------------------
    model.I = pyo.Set(initialize=cands, ordered=True)

    # Precomputed base dimensions for each candidate (constants from DATA)
    base_long = {i: L - 2.0 * i for i in cands}
    base_short = {i: W - 2.0 * i for i in cands}

    # ---- Variables ---------------------------------------------------
    # x[i] = 1 if candidate side length i is chosen
    model.x = pyo.Var(model.I, within=pyo.Binary)

    # Box dimensions (nonnegative; upper bounds from geometry)
    model.g = pyo.Var(model.I, within=pyo.NonNegativeReals, bounds=(0.0, L))
    model.h = pyo.Var(model.I, within=pyo.NonNegativeReals, bounds=(0.0, W))
    model.H = pyo.Var(model.I, within=pyo.NonNegativeReals, bounds=(0.0, d["max_side"]))

    # ---- Objective: maximise volume ----------------------------------
    def volume_rule(m):
        return sum(base_long[i] * base_short[i] * i * m.x[i] for i in m.I)

    model.obj = pyo.Objective(expr=volume_rule(model), sense=pyo.maximize)

    # ---- Constraint: exactly one candidate side length is chosen ------
    def pick_rule(m):
        return sum(m.x[i] for i in m.I) == 1

    model.pick_one = pyo.Constraint(rule=pick_rule)

    # ---- Linking: chosen candidate fixes box dimensions --------------
    # g[i] = (L - 2i) * x[i]  (upper bound by big-M when x[i]=1)
    def link_g_lo_rule(m, i):
        return m.g[i] >= base_long[i] - M * (1 - m.x[i])

    def link_g_hi_rule(m, i):
        return m.g[i] <= base_long[i] + M * (1 - m.x[i])

    def link_h_lo_rule(m, i):
        return m.h[i] >= base_short[i] - M * (1 - m.x[i])

    def link_h_hi_rule(m, i):
        return m.h[i] <= base_short[i] + M * (1 - m.x[i])

    def link_H_lo_rule(m, i):
        return m.H[i] >= i - M * (1 - m.x[i])

    def link_H_hi_rule(m, i):
        return m.H[i] <= i + M * (1 - m.x[i])

    model.link_g_lo = pyo.Constraint(model.I, rule=link_g_lo_rule)
    model.link_g_hi = pyo.Constraint(model.I, rule=link_g_hi_rule)
    model.link_h_lo = pyo.Constraint(model.I, rule=link_h_lo_rule)
    model.link_h_hi = pyo.Constraint(model.I, rule=link_h_hi_rule)
    model.link_H_lo = pyo.Constraint(model.I, rule=link_H_lo_rule)
    model.link_H_hi = pyo.Constraint(model.I, rule=link_H_hi_rule)

    return model


